  transforms) and write four custom properties from JS:
    el.style.setProperty('--tilt-rx', rxDeg + 'deg');
    el.style.setProperty('--tilt-ry', ryDeg + 'deg');
    el.style.setProperty('--tilt-gx', gxPct + '%');
    el.style.setProperty('--tilt-gy', gyPct + '%');
