        <section>
          <h3 className="font-sans text-sm font-semibold text-neutral-900">{title}</h3>
          <ul className="mt-4 flex flex-col gap-2.5">
            {rows.map((item) => (
              <ListRow key={item.name} item={item} />
            ))}
          </ul>
        </section>
      </div>
    );
  },
);

